sysdrills/05-sql-and-indexing/03-btree-d.solution:
export function btreeLevels(fanout, rows) {
  let levels = 1;
  let reach = fanout;
  while (reach < rows) {
    reach *= fanout;
    levels += 1;
  }
  return levels;
}

export function coldPageReads(fanout, rows, cachedLevels) {
  return btreeLevels(fanout, rows) - cachedLevels;
}

