sysdrills/05-sql-and-indexing/06-index-w.solution:
const SECONDS_PER_DAY = 86_400;

export function writesPerInsert(secondaryIndexes) {
  return 1 + secondaryIndexes;
}

export function indexWritesPerDay(insertsPerSec, secondaryIndexes) {
  return insertsPerSec * SECONDS_PER_DAY * writesPerInsert(secondaryIndexes);
}

