sysdrills/05-sql-and-indexing/08-index-m.solution:
export function indexBytes(rows, bytesPerEntry) {
  return rows * bytesPerEntry;
}

export function daysUntilRamFull(ramBytes, usedBytes, bytesPerEntry, rowsPerDay) {
  return (ramBytes - usedBytes) / (bytesPerEntry * rowsPerDay);
}
